/**
 * Test fixture only: a tiny hand written atlas manifest that covers every anatomical system and
 * every mapping rule. It is never loaded by the application (the real manifest is generated by
 * the asset pipeline into public/anatomy/manifest.json).
 */
import type { AnatomySystemId, AtlasManifest, AtlasStructure, TissueClass } from '../types'

export function fixtureStructure(id: string, name: string, system: AnatomySystemId, tissue: TissueClass, extra: Partial<AtlasStructure> = {}): AtlasStructure {
  return {
    id,
    name,
    system,
    tissue,
    side: id.endsWith('-left') ? 'L' : id.endsWith('-right') ? 'R' : null,
    center: [0, 1, 0],
    min: [-0.1, 0.9, -0.1],
    max: [0.1, 1.1, 0.1],
    triangles: 100,
    sourceObjects: [name],
    origin: 'z-anatomy',
    ...extra,
  }
}

const s = fixtureStructure

