const SYSTEM_IDS: AnatomySystemId[] = ['integumentary', 'skeletal', 'muscular', 'cardiovascular', 'respiratory', 'nervous', 'digestive', 'urinary', 'other']

export const FIXTURE_MANIFEST: AtlasManifest = {
  version: 1,
  generatedAt: '2026-11-14T00:00:00Z',
  bounds: { min: [-0.5, 0, -0.2], max: [0.5, 1.79, 0.2] },
  source: {
    name: 'Fixture atlas',
    url: 'https://example.invalid/fixture',
    license: 'CC BY-SA 4.0',
    sha256: '0'.repeat(64),
    retrievedAt: '2026-11-14',
    attribution: ['Fixture'],
    excluded: [],
  },
  systems: SYSTEM_IDS.map((id) => {
    const list = FIXTURE_STRUCTURES.filter((x) => x.system === id)
    return { id, label: id, file: `${id}.glb`, bytes: 1, triangles: list.reduce((n, x) => n + x.triangles, 0), structureCount: list.length }
  }),
  structures: FIXTURE_STRUCTURES,
}
